class Time:
    def __init__(self, nanoseconds, tz=None):
        self.nanoseconds = nanoseconds
        self.tz = tz

    @staticmethod
    def hydrate(nanoseconds, tz=None):
        """ Hydrator for `Time` and `LocalTime` values.

        :param nanoseconds:
        :param tz:
        :return: Time
        """
        if not isinstance(nanoseconds, int) or nanoseconds < 0:
            raise ValueError("nanoseconds must be a non-negative integer")
        if tz is not None and not isinstance(tz, str):
            raise ValueError("tz must be a string or None")
        return Time(nanoseconds, tz)

    def __repr__(self):
        return f"Time(nanoseconds={self.nanoseconds}, tz={self.tz})"

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
