def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    if key not in self.keys:
        raise ValueError("Key not found in the set")
    return self.keys.index(key)

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not hasattr(self, '_record'):
        return []

    record = self._record
    if not keys:
        return list(record.values())

    filtered_values = []
    for key in keys:
        if isinstance(key, int) and 0 <= key < len(record):
            filtered_values.append(record[key])
        elif isinstance(key, str) and key in record:
            filtered_values.append(record[key])
        else:
            raise ValueError(f"Invalid key or index: {key}")

    return filtered_values

def data(self, *keys):
    result = {}
    if keys:
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self):
                    raise IndexError(f"Index out of bounds: {key}")
                result[self.field_names[key]] = self.values[key]
            elif isinstance(key, str):
                if key not in self.field_names:
                    result[key] = None
                else:
                    index = self.field_names.index(key)
                    result[key] = self.values[index]
            else:
                raise TypeError(f"Unsupported key type: {type(key)}")
    else:
        for name, value in zip(self.field_names, self.values):
            result[name] = value
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    try:
        # Ensure there are at least two bytes of data to pop
        if len(self.data) < 2:
            raise ValueError("Not enough data to pop a 16-bit unsigned integer")

        # Extract the last two bytes and remove them from the data
        last_two_bytes = self.data[-2:]
        self.data = self.data[:-2]

        # Convert the big-endian byte sequence to a 16-bit unsigned integer
        return int.from_bytes(last_two_bytes, byteorder='big')

    except (AttributeError, TypeError, ValueError) as e:
        # Handle potential exceptions and provide a clear error message
        raise ValueError(f"Error popping 16-bit unsigned integer: {e}")

