def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not all(isinstance(f, tuple) and len(f) == 2 for f in fields):
        raise ValueError("Fields must be a list of tuples (name, type)")
    if not all(isinstance(srid, int) for srid in srid_map.values()):
        raise ValueError("SRID map values must be integers")

    class PointMeta(type):
        def __getattr__(cls, name):
            if name in fields:
                field_type = fields[name][1]
                return field_type
            raise AttributeError(f"'{cls.__name__}' object has no attribute '{name}'")

    class_point = type(name, (object,), {
        '__metaclass__': PointMeta,
        '__getattr__': PointMeta.__getattr__,
    })

    return class_point

def deprecated(message):
    """ Decorator for deprecating functions and methods. """
    def decorator(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
