def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    if lock is None:
        lock = threading.Lock()

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            func_key = key(*args, **kwargs)
            with lock:
                if func_key not in cache:
                    result = func(*args, **kwargs)
                    cache[func_key] = result
                return cache[func_key]
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            cache_key = (args, tuple(kwargs.items())) if typed else (args, tuple(kwargs.items()))
            current_time = timer()

            if cache_key in cache:
                result, item_time = cache[cache_key]
                if current_time - item_time <= ttl:
                    return result

            result = func(*args, **kwargs)
            cache[cache_key] = (result, current_time)

            if len(cache) > maxsize:
                cache = {k: v for k, v in cache.items() if current_time - v[1] <= ttl}

            return result

        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    if not isinstance(maxsize, int) or maxsize < 1:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    class MRUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.order = []

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (func, args, tuple(kwargs.items())) if self.typed else (func, tuple(args), tuple(kwargs.items()))
                if key in self.cache:
                    self.order.remove(key)
                    self.order.append(key)
                    return self.cache[key]
                result = func(*args, **kwargs)
                self.cache[key] = result
                self.order.append(key)
                if len(self.cache) > self.maxsize:
                    oldest_key = self.order.pop(0)
                    del self.cache[oldest_key]
                return result
            return wrapper

    if maxsize == 0:
        return lambda f: f
    else:
        return MRUCache(maxsize, typed)

def custom_lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """

    def decorator(func):
        cached_func = lru_cache(maxsize=maxsize, typed=typed)(func)

        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return cached_func(*args, **kwargs)
            except TypeError as e:
                if typed:
                    raise
                return cached_func(*args, **kwargs)

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache: Dict[Any, Any] = defaultdict(list)
            self.freq: Dict[int, Dict[Any, Any]] = defaultdict(dict)
            self.usage: Dict[int, int] = {}

        def __call__(self, func: Callable):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (func, args, tuple(kwargs.items())) if self.typed else (func, tuple(args), frozenset(kwargs.items()))
                if key in self.cache:
                    self.usage[key] += 1
                    self.move_to_bucket(key)
                    return self.cache[key]
                if len(self.cache) >= self.maxsize:
                    _, oldest_key = self.usage.popitem()
                    oldest_bucket = self.freq[len(self.cache)]
                    oldest_value = oldest_bucket.pop(oldest_key)
                    if not oldest_bucket:
                        del self.freq[len(self.cache)]
                    del self.cache[oldest_key]
                result = func(*args, **kwargs)
                self.cache[key] = result
                self.usage[key] = 1
                self.add_to_bucket(key, 1)
                return result

            def move_to_bucket(self, key):
                freq = self.usage[key] - 1
                if key in self.freq[freq]:
                    del self.freq[freq][key]
                self.add_to_bucket(key, freq + 1)

            def add_to_bucket(self, key, freq):
                if freq not in self.freq:
                    self.freq[freq] = {}
                self.freq[freq][key] = key

            return wrapper

    return LFUCache(maxsize, typed).__call__

