def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        def wrapper(self, *args, **kwargs):
            nonlocal cache, key, lock
            if lock is not None:
                lock.acquire()
            try:
                computed_key = key(self, args, kwargs)
                if computed_key not in cache:
                    result = method(self, *args, **kwargs)
                    cache[computed_key] = result
                else:
                    result = cache[computed_key]
            finally:
                if lock is not None:
                    lock.release()
            return result
        return wrapper
    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        try:
            if not isinstance(e, Exception):
                raise ValueError("The first argument must be an exception instance.")

            if not isinstance(max_level, int) or max_level < 0:
                raise ValueError("The second argument must be a non-negative integer.")

            if not isinstance(max_path_level, int) or max_path_level < 0:
                raise ValueError("The third argument must be a non-negative integer.")

            def format_exception(e, level):
                if level > max_level:
                    return "...[truncated]"
                try:
                    return f"{e.__class__.__name__}: {e}"
                except Exception as ex:
                    return f"Exception formatting error: {ex}"

            def format_traceback(traceback, level):
                if level > max_path_level:
                    return "...[truncated]"
                formatted_traceback = []
                for frame_record in traceback:
                    try:
                        filename, line_no, func_name, line = frame_record
                        formatted_traceback.append(f"  File \"{filename}\", line {line_no}, in {func_name}")
                    except Exception as ex:
                        formatted_traceback.append(f"  Error in traceback formatting: {ex}")
                return "\n".join(formatted_traceback)

            formatted_exception = format_exception(e, 0)
            if e.__traceback__:
                formatted_traceback = format_traceback(e.__traceback__, 0)
                formatted_exception += "\n" + formatted_traceback

            return formatted_exception
        except Exception as ex:
            return f"Error formatting exception: {ex}"

