def _legacy_mergeOrderings(orderings):
    merged = []
    order_set = set()

    while orderings:
        found = False
        for i, ordering in enumerate(orderings):
            if not set(ordering).isdisjoint(order_set):
                merged.append(ordering.pop(0))
                order_set.add(merged[-1])
                found = True
                break
        if not found:
            break

        new_orderings = []
        for ordering in orderings:
            if ordering:
                new_orderings.append(ordering)
            else:
                order_set.remove(merged.pop())

        orderings = new_orderings

    return merged + list(order_set)

