def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def is_valid_class_name(class_name):
        # Check if the class name is a valid string
        return isinstance(class_name, str) and class_name.isidentifier()

    def is_valid_class(class_obj):
        # Check if the class is a valid class object
        return isinstance(class_obj, type)

    def get_class_name(class_obj):
        # Get the name of the class object
        return class_obj.__name__

    def get_class_base_names(class_obj):
        # Get the names of the base classes of a class object
        return [base.__name__ for base in class_obj.__bases__]

    def find_class(class_name):
        # Find a class object by its name
        for cls in classes:
            if get_class_name(cls) == class_name:
                return cls
        raise ValueError(f"Class '{class_name}' not found in the list of classes")

    # Validate input
    if not isinstance(classes, list):
        raise TypeError("Input must be a list of classes")

    if not all(is_valid_class_name(class_name) for class_name in get_class_base_names(classes)):
        raise ValueError("Invalid class name in the list of classes")

    # Sort classes by their base class names
    classes.sort(key=lambda cls: tuple(get_class_base_names(cls)))

    # Remove classes that have duplicate base classes
    i = 0
    while i < len(classes):
        class_obj = classes[i]
        base_names = get_class_base_names(class_obj)
        j = i + 1
        while j < len(classes):
            other_class_obj = classes[j]
            other_base_names = get_class_base_names(other_class_obj)
            if base_names.issubset(other_base_names):
                classes.pop(i)
                i -= 1
                break
            j += 1
        i += 1

    # Return the minimal ordered equivalent of the list of base classes
    return classes

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise ValueError("The 'all' parameter must be a boolean.")

    attributes = []
    for name in dir(self):
        attribute = getattr(self, name)
        if callable(attribute) or name.startswith('__'):
            continue
        attributes.append((name, attribute.__doc__))

    return attributes if all else {name: description for name, description in attributes}

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if isinstance(sequence, tuple):
        for item in sequence:
            _normalizeargs(item, output)
    elif hasattr(sequence, 'interfaces'):
        output.extend(sequence.interfaces)
    elif hasattr(sequence, 'implements'):
        output.extend(sequence.implements)
    else:
        output.append(sequence)

    return output

