def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both d1 and d2 must be dictionaries")

    def _difference(subd1, subd2, current_level):
        if not isinstance(subd1, dict) or not isinstance(subd2, dict):
            raise ValueError("Both arguments must be dictionaries")
        if current_level == 0:
            return {}
        result = {}
        for k, v1 in subd1.items():
            if k not in subd2:
                result[k] = v1.copy()
            else:
                v2 = subd2[k]
                if isinstance(v1, dict) and isinstance(v2, dict):
                    diff = _difference(v1, v2, current_level - 1)
                    if diff:
                        result[k] = diff
                elif v1 != v2:
                    result[k] = v1.copy()
        return result

    return _difference(d1, d2, level)

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self._edges is None:
        raise ValueError("Histogram edges have not been set.")

    if not self._edges[0] <= coord <= self._edges[-1]:
        return

    try:
        index = int(coord * (self._edges.size - 1))
    except (TypeError, OverflowError):
        return

    if index < 0 or index >= self._edges.size - 1:
        return

    self._data[index] += weight

def _validate_labels(labels):
    import re

    key_regex = re.compile(r'^[a-zA-Z0-9_]*$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]*$')

    errors = []

    for key, value in labels.items():
        if isinstance(key, str):
            if not key_regex.match(key):
                errors.append({key: "Label key '{}' does not match the regex {}".format(key, key_regex.pattern)})
        else:
            errors.append({repr(key): "expected string or bytes-like object"})

        if isinstance(value, (list, tuple, set)):
            for item in value:
                if not isinstance(item, str):
                    errors.append({repr(item): "expected string or bytes-like object"})
                elif not value_regex.match(item):
                    errors.append({item: "Label value '{}' does not match the regex {}".format(item, value_regex.pattern)})
        elif not isinstance(value, str):
            errors.append({repr(value): "expected string or bytes-like object"})
        elif not value_regex.match(value):
            errors.append({value: "Label value '{}' does not match the regex {}".format(value, value_regex.pattern)})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default `observer_schema` from part
    of a Kubernetes resource, defined respectively by `manifest_dict` or
    `manifest_list`.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema.
    """
    observer_schema_dict = {}

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema_dict[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            observer_schema_dict[key] = generate_default_observer_schema_list(value)
        else:
            observer_schema_dict[key] = None

    if first_level:
        for field in ['apiVersion', 'kind', 'metadata.name']:
            if field in manifest_dict:
                observer_schema_dict[field] = manifest_dict[field]

    return observer_schema_dict

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A dictionary containing the default observer schema for each Kubernetes resource
    """
    default_observer_schema = {}
    for resource in app.spec.manifest:
        if not hasattr(resource, "observer_schema"):
            default_observer_schema[resource.kind] = {
                "kind": resource.kind,
                "apiVersion": resource.apiVersion,
                "spec": {}
            }
    return default_observer_schema

