def validate(self, inventory, extract_spec_version=False):
    if not isinstance(inventory, dict) or 'items' not in inventory:
        raise ValueError("Invalid inventory format")

    if extract_spec_version:
        if 'type' in inventory:
            spec_version = inventory['type']
        else:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version

    for item in inventory['items']:
        if not isinstance(item, dict) or 'name' not in item or 'quantity' not in item:
            raise ValueError("Invalid item format")

        if not isinstance(item['name'], str):
            raise ValueError("Invalid item name")

        if not isinstance(item['quantity'], (int, float)) or item['quantity'] < 0:
            raise ValueError("Invalid item quantity")

