def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("prior must be an instance of InventoryValidator")

    if self.current_version <= prior.current_version:
        raise ValueError("prior must be a prior version of the current inventory")

    if self.inventory_data != prior.inventory_data:
        raise ValueError("prior inventory data must match current inventory data")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None or version is None:
        raise ValueError("inventory and version must not be None")

    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    if not isinstance(version, str):
        raise TypeError("version must be a string")

    if version not in inventory:
        raise ValueError(f"version '{version}' not found in inventory")

    logical_path_map = {}

    for logical_path, file_info in inventory[version].items():
        content_files = file_info.get('content_files', [])
        logical_path_map[logical_path] = set(content_files)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity or not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a non-empty dictionary")

    if not manifest_files or not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a non-empty list")

    valid_files = set(manifest_files)

    for file_info in fixity.values():
        if not isinstance(file_info, dict):
            raise ValueError("Each file info in fixity must be a dictionary")

        if "filename" not in file_info or not isinstance(file_info["filename"], str):
            raise ValueError("Each file info must contain a non-empty filename string")

        filename = file_info["filename"]
        if filename not in valid_files:
            raise ValueError(f"File '{filename}' in fixity is not listed in manifest")

    return True

