def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for expr in args:
        # Apply absorption laws
        if isinstance(expr, tuple):
            if expr[1] == 'or' and expr[0] in expr[2:]:
                new_args.append(expr[0])
            elif expr[1] == 'and' and expr[0] in expr[2:]:
                new_args.append(expr[0])
        # Apply negative absorption laws
        if isinstance(expr, tuple):
            if expr[1] == 'and' and expr[0] in expr[2:]:
                new_args.append((expr[0], 'or', expr[2]))
            elif expr[1] == 'or' and expr[0] in expr[2:]:
                new_args.append((expr[0], 'and', expr[2]))
    return new_args

