def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("At least one command must be provided")

    if not args:
        raise ValueError("At least one argument must be provided")

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    combined_commands = [commands, args]
    command = flatten_list(combined_commands)

    try:
        if verbose:
            print(f"Running command: {' '.join(command)}")

        if hide_stderr:
            process = subprocess.Popen(command, cwd=cwd, env=env, stderr=subprocess.STDOUT, stdout=subprocess.PIPE)
        else:
            process = subprocess.Popen(command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        stdout, stderr = process.communicate()

        if process.returncode != 0:
            error_message = f"Command {' '.join(command)} failed with return code {process.returncode}"
            if stderr:
                error_message += f": {stderr.decode('utf-8').strip()}"
            raise subprocess.CalledProcessError(returncode=process.returncode, cmd=command, output=stdout.decode('utf-8').strip(), stderr=stderr.decode('utf-8').strip())

        if verbose:
            print(f"Command {' '.join(command)} succeeded")

        return stdout.decode('utf-8').strip()

    except FileNotFoundError:
        raise FileNotFoundError(f"Command {' '.join(command)} not found")
    except Exception as e:
        raise RuntimeError(f"An error occurred while running command {' '.join(command)}: {e}")

