def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        # Split the version string into components
        components = version.split('.')
        # Convert each component to an integer
        version_numbers = [int(num) for num in components]

        # Find the last non-zero component
        last_non_zero_index = -1
        for i, num in enumerate(version_numbers):
            if num != 0:
                last_non_zero_index = i

        # If all components are zero, increment the last component
        if last_non_zero_index == -1:
            version_numbers[-1] += 1
        else:
            # Increment the last non-zero component
            version_numbers[last_non_zero_index] += 1
            # Set all components after it to zero
            for i in range(last_non_zero_index + 1, len(version_numbers)):
                version_numbers[i] = 0

        # Convert the list of integers back to a version string
        return '.'.join([str(num) for num in version_numbers])

    except (ValueError, AttributeError):
        # Handle invalid input cases
        return "Invalid version format"

def validate_version_inventories(self, version_dirs):
    inventory_records = {}
    digests_to_check = {}

    for version_dir in version_dirs:
        inventory_path = f"{version_dir}/inventory"
        if not os.path.exists(inventory_path):
            raise ValueError(f"Inventory file missing for version {version_dir}")

        try:
            with open(inventory_path, 'r') as file:
                inventory_data = file.read()
                if version_dir not in inventory_records:
                    inventory_records[version_dir] = inventory_data
                else:
                    raise ValueError(f"Duplicate inventory found for version {version_dir}")

                # Check for content digests
                digests = extract_content_digests(inventory_data)
                for digest, info in digests.items():
                    if digest not in digests_to_check:
                        digests_to_check[digest] = info
                    elif digests_to_check[digest] != info:
                        raise ValueError(f"Digest mismatch for {digest} in version {version_dir}")

        except FileNotFoundError as e:
            raise FileNotFoundError(f"Error reading inventory file for version {version_dir}: {e}")
        except Exception as e:
            raise Exception(f"Error processing inventory file for version {version_dir}: {e}")

    return inventory_records, digests_to_check

def find_path_type(path):
    try:
        import os

        # Check if the given path is a directory
        if not os.path.isdir(path):
            return "Invalid path: not a directory"

        # Check if the path contains '0=*' file
        namaste_path = os.path.join(path, '0=*')
        if os.path.exists(namaste_path):
            with open(namaste_path, 'r') as file:
                first_line = file.readline().strip()

            # Determine the type based on the content of '0=*' file
            if first_line == 'OCFL Version: 1.0':
                return 'root'
            elif first_line == 'id:':
                return 'object'
            elif os.path.isfile(namaste_path):
                return 'file'
            else:
                return 'invalid inventory'

        # If '0=*' file does not exist, return the directory type based on contents
        contents = os.listdir(path)
        if any(elem.startswith('x/') for elem in contents):
            return 'root'  # Assuming 'x/' indicates an OCFL Storage Root
        elif any(elem.startswith('o/') for elem in contents):
            return 'object'  # Assuming 'o/' indicates an OCFL Object
        else:
            return 'unknown'

    except Exception as e:
        return f"Error: {str(e)}"

