def deep_merge_nodes(nodes):
    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            if isinstance(merged[key], dict) and isinstance(value_node.value, dict):
                # Recursively merge dictionaries
                merged[key] = deep_merge_dicts(merged[key], value_node.value)
            elif merged[key] != value_node.value:
                # If types or values are different, use the last one
                merged[key] = value_node.value
        else:
            merged[key] = value_node.value
    return [(ScalarNode(tag='tag:yaml.org,2002:str', value=key), MappingNode(tag='tag:yaml.org,2002:map', value=value)) for key, value in merged.items()]

