def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_args = {}
    remaining_args = []

    for arg in unparsed_arguments:
        found_match = False
        for name, parser in subparsers.items():
            try:
                # Attempt to parse the argument with the current subparser
                namespace = parser.parse_args([arg])
                parsed_args[name] = namespace
                found_match = True
                break
            except SystemExit:
                # If the subparser encounters an error, it will exit unexpectedly
                # We catch this and continue trying other subparsers
                continue
            except Exception as e:
                # Handle any other unexpected exceptions
                print(f"Error parsing argument with {name} subparser: {e}")
                continue

        if not found_match:
            remaining_args.append(arg)

    return parsed_args, remaining_args

def deep_merge_nodes(nodes):
    result = {}
    for key, value in nodes:
        if key.value in result:
            if isinstance(result[key.value], dict) and isinstance(value, ruamel.yaml.nodes.MappingNode):
                result[key.value] = deep_merge_nodes([(k, v) for k, v in zip(result[key.value].values(), value.value)])
            else:
                result[key.value] = value.value
        else:
            result[key.value] = value.value
    return [(ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=k), ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=[(ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=k2), v2) for k2, v2 in v.items()])) for k, v in result.items()]

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_args = {}
    remaining_args = []

    for argument in unparsed_arguments:
        for name, parser in subparsers.items():
            try:
                namespace, remaining = parser.parse_known_args([argument] + remaining_args)
                parsed_args[name] = namespace
                remaining_args = remaining
                break
            except Exception:
                continue

    return parsed_args, remaining_args

def size_to_bytes(size: str) -> int:
    size = size.strip().upper()
    if not size[-1].isnumeric():
        raise ValueError("Invalid size format")

    units = {'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4, 'P': 1000**5, 'E': 1000**6}
    number = int(size[:-1])
    unit = size[-1]

    if unit not in units:
        raise ValueError("Invalid unit")

    return number * units[unit]

