def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string:
        raise ValueError("Input string cannot be empty")
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    value = 0
    for char in string:
        if char not in alphabet:
            raise ValueError(f"Character '{char}' is not in the alphabet")
        index = alphabet.index(char)
        value = value * len(alphabet) + index

    return value

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise ValueError("Input must be a string.")
    if name.startswith('"') and name.endswith('"'):
        return name[1:-1]
    elif name.startswith("'") and name.endswith("'"):
        return name[1:-1]
    else:
        return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if re.search(r'[\\]', s):
            platform = 0
        else:
            platform = 1

    if platform == 0:
        pattern = r'(["\'])(?:(?=(\\?))\2.)*?\1|[^\\s"]+|\\.'
    elif platform == 1:
        pattern = r'["\'].*?["\']|\\.|[^\\s"]+'
    else:
        raise ValueError("Unsupported platform value")

    result = re.findall(pattern, s)
    return [r.replace('\\.', '.').replace('\\\\', '\\') for r in result]

def addignored(ignored):
    try:
        result = subprocess.run(['git', 'status', '--ignored'], capture_output=True, text=True, check=True)
        file_names = result.stdout.split('\n')
        filtered_files = [file.strip() for file in file_names if file.strip().endswith(tuple(ignored)) and not file.strip().startswith('ignored')]
        sorted_files = sorted(filtered_files)
        return ','.join(sorted_files)
    except subprocess.CalledProcessError as e:
        print(f"Error executing git command: {e}")
        return None

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        num, unit = frequency.split()
        num = int(num)
        if unit.endswith('s'):
            unit = unit[:-1]
        if unit == 'week':
            return datetime.timedelta(weeks=num)
        elif unit == 'day':
            return datetime.timedelta(days=num)
        elif unit == 'hour':
            return datetime.timedelta(hours=num)
        elif unit == 'minute':
            return datetime.timedelta(minutes=num)
        elif unit == 'second':
            return datetime.timedelta(seconds=num)
        else:
            raise ValueError(f"Unsupported time unit: {unit}")
    except (ValueError, AttributeError):
        raise ValueError(f"Invalid frequency format: {frequency}")

