def subprocess_run_helper(func, *args, timeout, extra_env=None):
    try:
        import subprocess
        import os

        # Create a complete command list with the additional arguments
        command = [func.__module__ + '.' + func.__name__] + list(args)

        # Create a new environment dictionary that includes the extra environment variables
        env = os.environ.copy()
        if extra_env:
            env.update(extra_env)

        # Run the command in a sub-process with the specified timeout and environment
        result = subprocess.run(command, timeout=timeout, env=env, capture_output=True, text=True)

        # Check if the command was successful
        if result.returncode == 0:
            return result.stdout
        else:
            raise Exception(f"Command failed with return code {result.returncode}: {result.stderr}")

    except FileNotFoundError:
        raise Exception(f"The function {func.__name__} cannot be found in the module {func.__module__}")
    except subprocess.TimeoutExpired:
        raise Exception(f"The command {func.__name__} timed out after {timeout} seconds")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if isinstance(commands, str):
            commands = [commands]
        cmd = [commands[0]] + args

        if verbose:
            print(f"Running: {' '.join(cmd)}")

        if env is None:
            env = dict(os.environ)

        process = subprocess.Popen(cmd, cwd=cwd, env=env, stderr=subprocess.PIPE if hide_stderr else None)
        stdout, stderr = process.communicate()

        if process.returncode != 0 and not hide_stderr:
            print(f"Error running command: {' '.join(cmd)}")
            print(stderr.decode('utf-8'))

        return process.returncode, stdout.decode('utf-8'), stderr.decode('utf-8') if stderr else None

    except Exception as e:
        print(f"Error running command: {' '.join(cmd)}")
        print(e)
        return -1, None, None

