def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json
    import os
    from logging import LogRecord, getLevelName

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config_data = json.load(file)
                config_dict[filename] = config_data
        except Exception as e:
            log_record = LogRecord('load_configurations', getLevelName(logging.ERROR), filename, 1, str(e), (), None)
            log_records.append(log_record)

    for overrides_file, override_values in overrides.items():
        try:
            with open(overrides_file, 'r') as file:
                override_data = json.load(file)
                for key, value in override_data.items():
                    if key in config_dict:
                        config_dict[key.update(override_values))
                    else:
                        config_dict[key] = value
        except Exception as e:
            log_record = LogRecord('load_configurations', getLevelName(logging.ERROR), overrides_file, 1, str(e), (), None)
            log_records.append(log_record)

    if resolve_env:
        for config in config_dict.values():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('${') and value.endswith('}'):
                    env_var = value[2:-1]
                    env_value = os.getenv(env_var)
                    if env_value:
                        config[key] = env_value
                    else:
                        log_record = LogRecord('load_configurations', getLevelName(logging.WARNING), filename, 1, f"Environment variable {env_var} not found", (), None)
                        log_records.append(log_record)

    return config_dict, log_records

def force_string(obj):
