        return None

def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds")
    hours = ticks // 3600000000000
    minutes = (ticks % 3600000000000) // 60000000000
    seconds = (ticks % 60000000000) // 1000000000
    microseconds = (ticks % 1000000000) // 1000
    return cls(hours, minutes, seconds, microseconds, tz=tz)

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    handlers = {
        (3, 4): cls.Bolt3_4,
        (3, 5): cls.Bolt3_5,
        (3, 6): cls.Bolt3_6,
        (4, 0): cls.Bolt4_0,
        (4, 1): cls.Bolt4_1,
        (4, 2): cls.Bolt4_2,
        (4, 3): cls.Bolt4_3,
    }

    if protocol_version is None:
        supported_versions = {version for version, handler in handlers.items()}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed as a tuple")
        supported_versions = {version for version, handler in handlers.items() if version == protocol_version}

    return {version: handlers[version] for version in supported_versions}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if not isinstance(values, Iterable):
        raise ValueError("The values parameter must be an iterable of strings.")

    bookmarks = []
    for value in values:
        if not isinstance(value, str):
            raise ValueError("All values in the iterable must be strings.")
        bookmarks.append(value)

    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).

    Args:
        seq (any): The input sequence or any other object.
        bufsize (int, optional): Buffer size for sequence conversion if applicable. Defaults to None.

    Returns:
        tuple: A tuple containing the derived sequence and its type.
    """
    if not isinstance(seq, (list, tuple)):
        return seq, type(seq)

    if bufsize is not None and bufsize > 0:
        try:
            # Assuming seq is an iterable, slice it to the specified bufsize
            seq = seq[:bufsize]
        except TypeError:
            # Handle the case where seq does not support slicing
            pass

    return seq, type(seq)

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    from agat.tools import histogram_to_graph

    if make_value is None:
        make_value = lambda content: content

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("Invalid get_coordinate value. Must be 'left', 'right', or 'middle'.")

    if not field_names or len(field_names) != 2:
        raise ValueError("Invalid field_names. Must be a tuple of 2 field names.")

    graph = histogram_to_graph(hist, make_value, get_coordinate, field_names, scale)
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            if zope.interface.implementer(implements=iface) in candidate.__class__.__bases__:
                if not any(item.startswith('implements=') for item in candidate.__class__.__bases__):
                    errors.append(f"Class {candidate.__class__.__name__} does not implement {iface}")
            elif zope.interface.provider(provides=iface) in candidate.__dict__.values():
                if not any(item.startswith('provides=') for item in candidate.__dict__.values()):
                    errors.append(f"Instance of {candidate.__class__.__name__} does not provide {iface}")
            else:
                errors.append(f"Candidate does not provide {iface}")

    required_methods = set(iface.names())
    defined_methods = {name for name in dir(candidate) if callable(getattr(candidate, name))}

    if required_methods - defined_methods:
        errors.extend(f"Missing method: {method}" for method in required_methods - defined_methods)

    required_attributes = {name for name in iface.names() if not callable(getattr(iface, name))}
    defined_attributes = {name for name in dir(candidate) if not callable(getattr(candidate, name))}

    if required_attributes - defined_attributes:
        errors.extend(f"Missing attribute: {attr}" for attr in required_attributes - defined_attributes)

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"Candidate does not claim to provide '{iface}'")

    candidate_methods = set(dir(candidate))
    interface_methods = set(iface.names())
    missing_methods = interface_methods - candidate_methods
    invalid_methods = []

    for method in missing_methods:
        candidate_method = getattr(candidate, method, None)
        interface_method = getattr(iface, method)
        signature_match = zope.interface.signature(candidate_method) == zope.interface.signature(interface_method)
        if not signature_match:
            invalid_methods.append(f"Method '{method}' does not match signature in interface '{iface}'")

    candidate_attributes = set(dir(candidate))
    interface_attributes = set(iface.names())
    missing_attributes = interface_attributes - candidate_attributes
    invalid_attributes = []

    for attribute in missing_attributes:
        if attribute not in ['__module__', '__dict__', '__weakref__', '__doc__', '__annotations__']:
            invalid_attributes.append(f"Attribute '{attribute}' is missing in candidate")

    errors = invalid_methods + invalid_attributes
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid('\n'.join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    if not hasattr(candidate, '__dict__'):
        return tentative

    for method_name in getattr(iface, '__dict__', {}).get('__methods__', []):
        if method_name.startswith('__') and method_name.endswith('__'):
            continue  # Skip special methods like __init__

        if not hasattr(candidate, method_name):
            return tentative

        candidate_method = getattr(candidate, method_name)
        iface_method = getattr(iface, method_name)

        if not callable(candidate_method) or not callable(iface_method):
            return tentative

        try:
            candidate_method()
            iface_method()
        except Exception:
            return tentative

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Step 1: Check for explicit metaclass provided
    if explicit_mc is not None:
        return explicit_mc

    # Step 2: Find the highest priority metaclass in the bases
    for base in bases:
        if '__metaclass__' in base.__dict__:
            return base.__dict__['__metaclass__']

    # Step 3: Check for __class__ in the bases which is used in Python 2
    for base in bases:
        if '__class__' in base.__dict__:
            return base.__dict__['__class__']

    # Step 4: Use the first base's metaclass as a fallback
    if bases:
        return bases[0].__class__

    # Step 5: Default to type if no metaclasses are found
    return type

def pop(self, key, default=None):
    if key in self:
        return self[key].pop()
    elif default is not None:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem from an empty dictionary")

    try:
        key, value = self.most_frequent.get_nowait()
        del self[key]
        return key, value
    except KeyError:
        raise KeyError("popitem from an empty dictionary")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not hasattr(self, '_access_order') or not self._access_order:
        raise KeyError("popitem(): dictionary is empty")
    key = self._access_order[-1]
    value = self._dict[key]
    del self._dict[key]
    del self._access_order[-1]
    return (key, value)

def popitem(self):
    if not self:
        raise KeyError("popitem from an empty ordered dictionary")
    key, value = random.choice(list(self.items()))
    del self[key]
    return key, value

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    try:
        if not isinstance(timestr, str):
            raise TypeError("Input must be a string")

        if tzinfos is not None and not callable(tzinfos):
            tzinfos_processed = {}
            for key, value in tzinfos.items():
                if isinstance(value, tzoffset):
                    tzinfos_processed[key] = value
                elif isinstance(value, int):
                    tzinfos_processed[key] = tzoffset(key, value)
                else:
                    tzinfos_processed[key] = gettz(value)
            tzinfos = tzinfos_processed

        result = dateutil.parser.parse(timestr, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)

        if default is not None:
            if isinstance(default, dateutil.parser._BaseDateTime):
                for attr_name in ('year', 'month', 'day', 'hour', 'minute', 'second', 'microsecond'):
                    value = getattr(result, attr_name)
                    if value is not None:
                        setattr(default, attr_name, value)
                result = default

        return result
    except (ParserError, TypeError, OverflowError) as e:
        raise e
    except Exception as e:
        raise ValueError("An unexpected error occurred: " + str(e))

def identify_request(request: RequestType) -> Optional[DiasporaRequest]:
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if not isinstance(request, RequestType):
        raise ValueError("Invalid request type")

    if isinstance(request, PublicMessage):
        return DiasporaRequest()
    elif isinstance(request, PrivateMessage):
        return DiasporaRequest()
    elif isinstance(request, LegacyPayload):
        return DiasporaRequest()
    else:
        return None

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    try:
        return dt.strftime("%Y-%m-%d %H:%M:%S")
    except AttributeError:
        raise ValueError("Input must be a datetime object")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    new_text = []
    start_tag = "<"
    end_tag = ">"
    for char in text:
        if char == "`" and new_text:
            in_code_block = not in_code_block
        if not in_code_block:
            if char == start_tag and new_text[-1] not in [start_tag, "`"]:
                tag = []
                while char != end_tag:
                    tag.append(char)
                    if not tag:
                        raise ValueError("Unterminated tag")
                    char = next(text)  # We are changing the text iterator here
                new_tag = "".join(tag)
                tags.add(new_tag)
                if replacer:
                    try:
                        new_tag = replacer(new_tag[1:-1])  # Remove < and >
                    except Exception as e:
                        print(f"Error replacing tag {new_tag[1:-1]}: {e}")
                new_text.append(new_tag)
            else:
                new_text.append(char)
    return tags, "".join(new_text)

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not tag:
        return False
    if not tag[0].isalpha():
        return False
    for char in tag[1:]:
        if not (char.isalnum() or char == '-' or char == '_'):
            return False
    return True

def xml_children_as_dict(node):
    result = {}
    if node is None:
        raise ValueError("The input node cannot be None")
    for child in node:
        if child.tag not in result:
            result[child.tag] = child.text if child.text else None
        else:
            if isinstance(result[child.tag], list):
                result[child.tag].append(child.text if child.text else None)
            else:
                result[child.tag] = [result[child.tag], child.text if child.text else None]
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle == entity_handle:
        return True
    else:
        return False

