def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    from lxml import etree

    try:
        if document.startswith('{'):
            # Parse as JSON
            data = json.loads(document)
        elif document.startswith('<?xml'):
            # Parse as XRD
            root = etree.fromstring(document)
            data = {}
            for entry in root.findall('.//template[@rel="http://salmon.plet.txt/rel/post-back"]'):
                data['endpoint'] = entry.get('href')
                break
        else:
            raise ValueError("Unsupported webfinger document format")

        return data
    except json.JSONDecodeError as e:
        raise ValueError("Invalid JSON format") from e
    except etree.XMLSyntaxError as e:
        raise ValueError("Invalid XRD format") from e

