def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if not handle:
        raise ValueError("Handle cannot be empty")

    url = f"https://{handle}/.well-known/webfinger"
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to retrieve webfinger document: {e}")

    try:
        root = ET.fromstring(response.content)
        subject = root.find("{http://www.w3.org/ns/xrd#}Subject").text
        links = root.findall("{http://www.w3.org/ns/xrd#}Link")
        parsed_data = {
            "subject": subject,
            "profiles": []
        }
        for link in links:
            profile = {
                "rel": link.get("{http://www.w3.org/1999/xlink}rel"),
                "href": link.get("{http://www.w3.org/1999/xlink}href")
            }
            parsed_data["profiles"].append(profile)
        return parsed_data
    except ET.ParseError as e:
        raise Exception(f"Failed to parse response: {e}")

