def validate_from_content(cls, spec_content: str = None) -> Dict[str, any]:
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise ValueError("spec_content cannot be None")

        try:
            spec_data = yaml.safe_load(spec_content)
        except ParserError as e:
            raise IRValidatorException(f"Error parsing YAML content: {e}")

        required_fields = cls.get_required_fields()
        missing_fields = [field for field in required_fields if field not in spec_data]

        if missing_fields:
            raise IRValidatorException(f"Missing required fields: {missing_fields}")

        return spec_data

    @classmethod
    def get_required_fields(cls) -> list:
        """Get the list of required fields for the spec"""
        # Define the required fields here
        return ["field1", "field2", "field3"]

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise ValueError("yaml_file parameter is required")

        try:
            with open(yaml_file, 'r') as file:
                data = yaml.safe_load(file)
                if not data:
                    raise IRValidatorException("YAML file is empty")

                # Add validation logic here for mandatory fields
                required_fields = {'field1', 'field2'}  # Replace with actual required fields
                missing_fields = required_fields - set(data.keys())
                if missing_fields:
                    raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing_fields)}")

                return data
        except FileNotFoundError:
            raise FileNotFoundError(f"YAML file not found: {yaml_file}")
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML file: {e}")

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("Input must be a dictionary")

    if 'include' not in parser_dict:
        raise KeyError("Dictionary must contain 'include' key")

    include_dict = parser_dict['include']
    if not isinstance(include_dict, dict):
        raise ValueError("Value of 'include' key must be a dictionary")

    resolved_dict = {}
    for key, value in include_dict.items():
        if key in parser_dict:
            raise KeyError(f"Key '{key}' conflicts with top-level keys")

        resolved_dict[key] = value

    return resolved_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        # Step 1: Retrieve default values from spec
        spec_defaults = self.get_spec().get('defaults', {})

        # Step 2: Retrieve values from other sources (e.g., environment variables, configuration files)
        other_sources_values = self.get_values_from_other_sources()

        # Step 3: Combine defaults and values from other sources
        combined_values = {**spec_defaults, **other_sources_values}

        # Step 4: Return the combined values
        return combined_values
    except Exception as e:
        # Handle exceptions (e.g., log the error, return a default dictionary, etc.)
        print(f"An error occurred: {e}")
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
