def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if isinstance(condition, dict):
                for key, value in condition.items():
                    if key in args and args[key] == value:
                        matched_args.append(option['name'])
            elif callable(condition):
                if condition(command_name, args):
                    matched_args.append(option['name'])
    return matched_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > 10:
            raise ValueError(f"Argument '{arg}' exceeds the maximum length of 10 characters.")
    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg not in available_choices:
            raise ValueError(f"Invalid choice: {arg}. Available choices are: {available_choices}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :raise ValueError: If any argument is not within the valid range.
    """
    if not args:
        raise ValueError("No arguments provided")

    min_val = min(args)
    max_val = max(args)

    if min_val < -100 or max_val > 100:
        raise ValueError("Argument values are out of the valid range (-100 to 100)")

    if min_val > max_val:
        raise ValueError("Minimum value is greater than maximum value")

